BFS
function [ out, Parent ] = BFSGraph, start, End, parent, ROW
visited = zeros(1, ROW);
queue = [];
queue = [queue, start];
visited(start) = 1;
while queue
u = queue(1);
queue(1) = [];
for i = 1:ROW
if (visited(i)==0)&&(Graph(u, i)¿0)
queue = [queue, i];
visited(i) = 1;
parent(i) = u;
end

end
end
out = visited(End);
Parent = parent;
end

Ford fulkerson
function [max flow, Remain] = Ford fulkerson(Graph, s, e, ROW)
NUM INF = inf;
parent = zeros(1, ROW);
parent(:) = -1;
max flow = 0;
start = s;
End = e;
[out, parent] = BFS (Graph, start, End, parent, ROW);
while out
path flow = NUM INF;
start = End;
while start = s
path flow = min(path flow, Graph(parent(1, start), start));
start = parent(1, start);
end
max flow = max flow + path flow;
v = End;
while v = start
u = parent(1, v);
Graph(u, v) = Graph(u, v) - path flow;
Graph(v, u) = Graph(v, u) + path flow;
v = parent(1, v);
end
[out, parent] = BFS(Graph, start, End, parent, ROW);
end
Remain = Graph;
end

Channel
function [Graph Channel] = Channel(Channel width, Channel density, ac)
v = 1 - 0.266.*1.40.*Channel density;
Graph Channel = v.*ac.*Channel width.*Channel density;
end

Stairs
function [Graph Stairs] = Stairs(Stairs width, Stairs density, ac)
v = 1 - 0.266.*1.08.*Stairs density;
Graph Stairs = v.*ac.*Stairs width.*Stairs density;
end

Main
function[Max flow, Flow, Remain, Time] = Main(G,ac)%Stairs width, Stairs density, Chan-
nel width, Channel density, Graph enter,
Graph exit, ac)%, Emergency)
Graph = G;%Channel(Channel width, Channel density, ac) + Stairs(Stairs width, Stairs density,
ac) + Graph enter +
(Graph exit./5.*ac);
ROW = length(Graph);
Graph(2:ROW,:) = Graph(2:ROW,:).*ac./5;
Total = sum(Graph(1,:))
% Emergency situation
% Only leaving is allowed
% Use this section by uncommenting all about this
%{
if ∼isempty(Emergency)
Graph(2:ROW,Emergency) = 0;
Ge = Graph;
t = [];
for i = 1:length(Emergency)
v = sum(Graph(Emergency(i),:),2);
t = [t, ac*Graph(1,Emergency(i))/v];
end
Graph(1, Emergency) = 0;
Graph(Emergency, :) = 0;
end
%}
i = 0;
Max flow = [];
Flow = zeros(ROW, ROW, 1);
Remain = zeros(ROW, ROW, 1);
while Total¿0.5
i = i+1;
mf = 0;
%{
if ∼isempty(Emergency)
for j = 1:length(Emergency)
if i*ac-t(j)¡ac
Graph(1,:) = Graph(1,:) + Ge(Emergency(j),:).*(min(t(j),i*ac)-i*ac+ac)./ac;

mf = mf+Graph(1,ROW);
Graph(1,ROW) = 0;
end
end
end
%}
Copy = Graph;
[max flow, Copy] = Ford fulkerson(Copy, 1, ROW, ROW);
Remain(:, :, i) = Copy;
Temp = Graph - Copy;
Temp(Temp¡0) = 0;
%{
if isempty(Emergency)
for j = 1:length(Emergency)
if i*ac-t(j)¡ac
Temp(Emergency(j),:) = Temp(Emergency(j),:) + Ge(Emergency(j),:);
end
end
end
%}
Flow(:, :, i) = Temp;
max flow = max flow + mf;
Max flow = [Max flow, max flow];
Total = Total - max flow
Graph(1, :) = Graph(1, :) - Temp(1, :);
end
Time = i*ac;
end
